const tf = require('@tensorflow/tfjs');
const cocoSsd = require('@tensorflow-models/coco-ssd');

const ArgumentType = require('../../extension-support/argument-type');
const BlockType = require('../../extension-support/block-type');
const Cast = require('../../util/cast');
const Video = require('../../io/video');

const training = require('./training.json');
const testing = require('./testing.json');

const SPECIES = ['setosa', 'virginica', 'versicolor'];
const DEFAULT_EPOCHS = 20;
const VIDEO_DIMENSIONS = [480, 360];

class Scratch3DeepScratch {
    constructor (runtime) {
        this.runtime = runtime;
        this.epochs = DEFAULT_EPOCHS;
        this.model = null;
        this.objectModel = null;
        this.objectModelPromise = null;
        this.predictions = [];
        this.status = 'ready';
        this.lastError = '';
        this.trainingAccuracy = 0;
        this.testingAccuracy = 0;
        this.loss = 0;
        this.runtime.on('PROJECT_LOADED', () => this.reset());
    }

    getInfo () {
        return {
            id: 'deepscratch',
            name: 'DeepScratch',
            color1: '#1ebdad',
            color2: '#0aab9b',
            color3: '#07867a',
            blocks: [
                {
                    opcode: 'setEpochs',
                    blockType: BlockType.COMMAND,
                    text: 'set training epochs to [EPOCHS]',
                    arguments: {
                        EPOCHS: {type: ArgumentType.NUMBER, defaultValue: DEFAULT_EPOCHS}
                    }
                },
                {
                    opcode: 'trainFlowerModel',
                    blockType: BlockType.COMMAND,
                    text: 'train flower neural network'
                },
                {
                    opcode: 'predictFlower',
                    blockType: BlockType.REPORTER,
                    text: 'predict flower sepal [SL] [SW] petal [PL] [PW]',
                    arguments: {
                        SL: {type: ArgumentType.NUMBER, defaultValue: 5.1},
                        SW: {type: ArgumentType.NUMBER, defaultValue: 3.5},
                        PL: {type: ArgumentType.NUMBER, defaultValue: 1.4},
                        PW: {type: ArgumentType.NUMBER, defaultValue: 0.2}
                    }
                },
                '---',
                {
                    opcode: 'getTrainingAccuracy',
                    blockType: BlockType.REPORTER,
                    text: 'training accuracy %'
                },
                {
                    opcode: 'getTestingAccuracy',
                    blockType: BlockType.REPORTER,
                    text: 'testing accuracy %'
                },
                {
                    opcode: 'getLoss',
                    blockType: BlockType.REPORTER,
                    text: 'training loss'
                },
                {
                    opcode: 'getStatus',
                    blockType: BlockType.REPORTER,
                    text: 'machine learning status'
                },
                {
                    opcode: 'getLastError',
                    blockType: BlockType.REPORTER,
                    text: 'machine learning error'
                },
                '---',
                {
                    opcode: 'setVideo',
                    blockType: BlockType.COMMAND,
                    text: 'turn camera [STATE]',
                    arguments: {
                        STATE: {type: ArgumentType.STRING, menu: 'videoState', defaultValue: 'on'}
                    }
                },
                {
                    opcode: 'detectObjects',
                    blockType: BlockType.COMMAND,
                    text: 'detect objects with confidence above [CONFIDENCE] %',
                    arguments: {
                        CONFIDENCE: {type: ArgumentType.NUMBER, defaultValue: 50}
                    }
                },
                {
                    opcode: 'getObjectCount',
                    blockType: BlockType.REPORTER,
                    text: 'number of objects'
                },
                {
                    opcode: 'getObjectProperty',
                    blockType: BlockType.REPORTER,
                    text: '[PROPERTY] of object [INDEX]',
                    arguments: {
                        PROPERTY: {type: ArgumentType.STRING, menu: 'objectProperty', defaultValue: 'name'},
                        INDEX: {type: ArgumentType.NUMBER, defaultValue: 1}
                    }
                },
                {
                    opcode: 'reset',
                    blockType: BlockType.COMMAND,
                    text: 'reset machine learning'
                }
            ],
            menus: {
                videoState: ['on', 'on flipped', 'off'],
                objectProperty: ['name', 'confidence', 'x position', 'y position', 'width', 'height']
            }
        };
    }

    setEpochs (args) {
        this.epochs = Math.max(1, Math.min(500, Math.round(Cast.toNumber(args.EPOCHS))));
    }

    _irisTensors (rows) {
        const inputs = tf.tensor2d(rows.map(row => [
            row.sepal_length,
            row.sepal_width,
            row.petal_length,
            row.petal_width
        ]));
        const labels = tf.tensor2d(rows.map(row => SPECIES.map(species => species === row.species ? 1 : 0)));
        return {inputs, labels};
    }

    async trainFlowerModel () {
        if (this.status === 'training') return;
        this.status = 'training';
        this.lastError = '';
        if (this.model) this.model.dispose();
        const train = this._irisTensors(training);
        const test = this._irisTensors(testing);
        try {
            this.model = tf.sequential();
            this.model.add(tf.layers.dense({inputShape: [4], units: 10, activation: 'relu'}));
            this.model.add(tf.layers.dense({units: 8, activation: 'relu'}));
            this.model.add(tf.layers.dense({units: 3, activation: 'softmax'}));
            this.model.compile({
                optimizer: tf.train.adam(0.02),
                loss: 'categoricalCrossentropy',
                metrics: ['accuracy']
            });
            const history = await this.model.fit(train.inputs, train.labels, {
                epochs: this.epochs,
                shuffle: true,
                yieldEvery: 'epoch'
            });
            const losses = history.history.loss;
            const accuracies = history.history.acc || history.history.accuracy;
            this.loss = losses[losses.length - 1];
            this.trainingAccuracy = accuracies[accuracies.length - 1] * 100;
            const evaluation = this.model.evaluate(test.inputs, test.labels);
            const accuracyTensor = Array.isArray(evaluation) ? evaluation[1] : evaluation;
            this.testingAccuracy = (await accuracyTensor.data())[0] * 100;
            tf.dispose(evaluation);
            this.status = 'trained';
        } catch (error) {
            this.lastError = error.message;
            this.status = 'error';
        } finally {
            tf.dispose([train.inputs, train.labels, test.inputs, test.labels]);
        }
    }

    predictFlower (args) {
        if (!this.model) return '';
        return tf.tidy(() => {
            const input = tf.tensor2d([[
                Cast.toNumber(args.SL), Cast.toNumber(args.SW),
                Cast.toNumber(args.PL), Cast.toNumber(args.PW)
            ]]);
            const values = this.model.predict(input).dataSync();
            let best = 0;
            for (let index = 1; index < values.length; index++) {
                if (values[index] > values[best]) best = index;
            }
            return SPECIES[best];
        });
    }

    getTrainingAccuracy () {
        return Math.round(this.trainingAccuracy * 100) / 100;
    }

    getTestingAccuracy () {
        return Math.round(this.testingAccuracy * 100) / 100;
    }

    getLoss () {
        return Math.round(this.loss * 10000) / 10000;
    }

    getStatus () {
        return this.status;
    }

    getLastError () {
        return this.lastError;
    }

    setVideo (args) {
        const video = this.runtime.ioDevices.video;
        const state = Cast.toString(args.STATE);
        if (state === 'off') {
            video.disableVideo();
            return;
        }
        video.mirror = state !== 'on flipped';
        return video.enableVideo();
    }

    async _getObjectModel () {
        if (this.objectModel) return this.objectModel;
        if (!this.objectModelPromise) {
            this.status = 'loading object model';
            const modelURL = new URL('ninja-extensions/models/coco-ssd/model.json', document.baseURI).href;
            this.objectModelPromise = cocoSsd.load({base: 'lite_mobilenet_v2', modelUrl: modelURL})
                .then(model => {
                    this.objectModel = model;
                    this.status = 'ready';
                    return model;
                })
                .catch(error => {
                    this.objectModelPromise = null;
                    this.lastError = error.message;
                    this.status = 'error';
                    throw error;
                });
        }
        return this.objectModelPromise;
    }

    async detectObjects (args) {
        this.lastError = '';
        try {
            const frame = this.runtime.ioDevices.video.getFrame({
                format: Video.FORMAT_CANVAS,
                dimensions: VIDEO_DIMENSIONS,
                mirror: false
            });
            if (!frame) throw new Error('Turn the camera on before detecting objects.');
            const model = await this._getObjectModel();
            const threshold = Math.max(0, Math.min(100, Cast.toNumber(args.CONFIDENCE))) / 100;
            this.predictions = await model.detect(frame, 20, threshold);
            this.status = 'ready';
        } catch (error) {
            this.predictions = [];
            this.lastError = error.message;
            this.status = 'error';
        }
    }

    getObjectCount () {
        return this.predictions.length;
    }

    getObjectProperty (args) {
        const prediction = this.predictions[Math.max(0, Math.round(Cast.toNumber(args.INDEX)) - 1)];
        if (!prediction) return '';
        const [x, y, width, height] = prediction.bbox;
        switch (Cast.toString(args.PROPERTY)) {
        case 'name': return prediction.class;
        case 'confidence': return Math.round(prediction.score * 1000) / 10;
        case 'x position': return Math.round(x + (width / 2) - 240);
        case 'y position': return Math.round(180 - y - (height / 2));
        case 'width': return Math.round(width);
        case 'height': return Math.round(height);
        default: return '';
        }
    }

    reset () {
        if (this.model) this.model.dispose();
        this.model = null;
        this.predictions = [];
        this.trainingAccuracy = 0;
        this.testingAccuracy = 0;
        this.loss = 0;
        this.lastError = '';
        this.status = 'ready';
    }
}

module.exports = Scratch3DeepScratch;
